INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Adressverwaltung in IPv6 einfacher wegen des großen Adressraums?', 2, '[{"text": "Ja", "correct": true, "because": "Weniger Konflikte durch 2^128"}, {"text": "Nein", "correct": false, "because": "Größe erleichtert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Adressen bietet der IPv6-Adressraum?', 3, '[{"text": "2^128", "correct": true, "because": "128 Bits definieren Raum"}, {"text": "2^64", "correct": false, "because": "Nur Interface-ID bei /64"}, {"text": "2^32", "correct": false, "because": "IPv4-Größe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode nutze ich für die Adressverwaltung in großen Netzen?', 4, '[{"text": "DHCPv6", "correct": true, "because": "Zentralisierte Zuweisung"}, {"text": "Manuelle Vergabe", "correct": false, "because": "Unpraktisch bei Größe"}, {"text": "Zufällige Auswahl", "correct": false, "because": "Unkontrolliert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IPv6 hat 2^128 Adressen. b) Adressverwaltung ist immer automatisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, auch manuell möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Adressverwaltung in IPv6?', 5, '[{"text": "Adressknappheit", "correct": true, "because": "2^128 ist riesig"}, {"text": "Subnetzplanung", "correct": false, "because": "Wichtig für Struktur"}, {"text": "Präfixzuweisung", "correct": false, "because": "Kern der Verwaltung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der große Adressraum IPv4-Probleme löst?', 2, '[{"text": "Ja", "correct": true, "because": "Behebt Knappheit"}, {"text": "Nein", "correct": false, "because": "Erweitert Kapazität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft bei der Verwaltung eines großen Adressraums?', 3, '[{"text": "DHCPv6", "correct": true, "because": "Automatisiert Zuweisung"}, {"text": "NAT", "correct": false, "because": "IPv4-spezifisch"}, {"text": "ARP", "correct": false, "because": "MAC-Adressauflösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet der große Adressraum für die Verwaltung?', 5, '[{"text": "Keine Adresskonflikte", "correct": true, "because": "Enorme Kapazität"}, {"text": "Einfachere Subnetzplanung", "correct": true, "because": "Mehr Flexibilität"}, {"text": "Kleinere Subnetze", "correct": false, "because": "Größere möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) 2^128 macht NAT überflüssig. b) Verwaltung ist immer manuell. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, Automatisierung möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Adressverwaltung in IPv6?', 4, '[{"text": "Präfixzuweisung", "correct": false, "because": "Strukturiert Netz"}, {"text": "Automatisierung", "correct": false, "because": "Erleichtert Verwaltung"}, {"text": "Adresswiederverwendung", "correct": true, "because": "Genug Adressen vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der große Adressraum nur für große Netze nützlich?', 2, '[{"text": "Nein", "correct": true, "because": "Vorteil auch für kleine Netze"}, {"text": "Ja", "correct": false, "because": "Universell nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen die Adressverwaltung?', 4, '[{"text": "SLAAC", "correct": true, "because": "Autokonfiguration"}, {"text": "DHCPv6", "correct": true, "because": "Zentralisierte Verwaltung"}, {"text": "NAT", "correct": false, "because": "IPv4-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der große Adressraum die Verwaltung komplizierter macht. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Eher vereinfacht durch Größe"}, {"text": "Ja", "correct": false, "because": "Flexibilität erhöht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Verwaltung eines großen Adressraums?', 3, '[{"text": "Effiziente Subnetzplanung", "correct": true, "because": "Nutzt Raum optimal"}, {"text": "Manuelle Zuweisung", "correct": false, "because": "Unpraktisch"}, {"text": "Kürzeste Adressen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IPv6 hat genug Adressen für alle Geräte. b) Verwaltung ist nur mit DHCPv6 möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, auch SLAAC"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen vermeidet der große Adressraum?', 5, '[{"text": "Adressknappheit", "correct": true, "because": "2^128 ist riesig"}, {"text": "NAT-Nutzung", "correct": true, "because": "Direkte Adressierung möglich"}, {"text": "Schnellere Routing", "correct": false, "because": "Nicht direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Adressverwaltung unwichtig?', 3, '[{"text": "Subnetzstruktur", "correct": false, "because": "Wichtig für Organisation"}, {"text": "Automatisierung", "correct": false, "because": "Erleichtert Prozess"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Macht der große Adressraum DHCPv6 überflüssig?', 2, '[{"text": "Nein", "correct": true, "because": "Verwaltung bleibt nötig"}, {"text": "Ja", "correct": false, "because": "Ergänzt SLAAC"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der große Adressraum Subnetzplanung erleichtert?', 3, '[{"text": "Ja", "correct": true, "because": "Mehr Flexibilität"}, {"text": "Nein", "correct": false, "because": "Größe hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Größe wähle ich für eine effiziente Adressverwaltung?', 4, '[{"text": "/48", "correct": true, "because": "Viele Subnetze möglich"}, {"text": "/128", "correct": false, "because": "Nur eine Adresse"}, {"text": "/64", "correct": false, "because": "Weniger Subnetze"}]');
